function Metric({label,value,detail,icon:Icon}:{label:string;value:string|number;detail:string;icon?:typeof Users}){return <article className="ds-metric"><div><span>{label}</span>{Icon&&<Icon size={18}/>}</div><strong>{value}</strong><small>{detail}</small></article>;}
function CourseFilter({courses,value,onChange}:{courses:DemoCourse[];value:string;onChange:(id:string)=>void}){return <HelpLabel>Curso<select value={value} onChange={e=>onChange(e.target.value)}><option value="all">Todos os cursos</option>{courses.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></HelpLabel>;}
function CompassIcon(){return <ClipboardCheck size={16}/>;}
